(function(){document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll(".widget-toggle");e.forEach(function(e){e.addEventListener("click",function(){const t=this.closest("[data-widget]");if(!t)return;const n=t.querySelector(".widget-content"),e=t.querySelector(".widget-arrow"),s=this.getAttribute("aria-expanded")==="true";s?(n.classList.add("collapsed"),this.setAttribute("aria-expanded","false"),e&&(e.style.transform="rotate(-90deg)")):(n.classList.remove("collapsed"),this.setAttribute("aria-expanded","true"),e&&(e.style.transform="rotate(0deg)"))})})})})()